import{_ as t,o as i,c as o,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Conditional visibility","description":"Show and hide blocks depending on entered values.","frontmatter":{"title":"Conditional visibility","description":"Show and hide blocks depending on entered values."},"headers":[],"relativePath":"en/seiten/sichtbarkeit.md","filePath":"en/seiten/sichtbarkeit.md","lastUpdated":1787319236000}'),a={name:"en/seiten/sichtbarkeit.md"};function s(r,e,l,d,c,h){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="conditional-visibility" tabindex="-1">Conditional visibility <a class="header-anchor" href="#conditional-visibility" aria-label="Permalink to &quot;Conditional visibility&quot;">​</a></h1><p>Blocks can be shown or hidden depending on the values of other fields. This turns a static page into a form that reacts to input.</p><div class="warning custom-block"><p class="custom-block-title">Top plan only</p><blockquote><p><em>Upgrade to Pro to show or hide blocks based on form field values.</em></p></blockquote></div><h2 id="creating-a-condition" tabindex="-1">Creating a condition <a class="header-anchor" href="#creating-a-condition" aria-label="Permalink to &quot;Creating a condition&quot;">​</a></h2><ol><li>Select the block that should appear conditionally.</li><li>In the block settings, open the <strong>Visibility</strong> section.</li><li>Choose <strong>Field</strong>, <strong>Condition</strong>, and <strong>Value</strong>.</li></ol><p>Use <strong>Remove</strong> to delete the condition again.</p><h2 id="available-conditions" tabindex="-1">Available conditions <a class="header-anchor" href="#available-conditions" aria-label="Permalink to &quot;Available conditions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Useful for</th></tr></thead><tbody><tr><td><strong>is empty</strong> / <strong>is not empty</strong></td><td>any field type</td></tr><tr><td><strong>is true</strong> / <strong>is false</strong></td><td>checkmark, decision</td></tr><tr><td><strong>equals</strong> / <strong>does not equal</strong></td><td>select, text, numbers</td></tr><tr><td><strong>is greater than</strong> / <strong>is less than</strong></td><td>numbers, date</td></tr></tbody></table><h2 id="feedback-in-the-editor" tabindex="-1">Feedback in the editor <a class="header-anchor" href="#feedback-in-the-editor" aria-label="Permalink to &quot;Feedback in the editor&quot;">​</a></h2><p>The editor shows what currently applies:</p><ul><li><em>Visible when {condition}</em> — the configured rule</li><li><strong>Currently visible</strong> or <strong>Currently hidden</strong> — the state given the values entered right now</li></ul><div class="tip custom-block"><p class="custom-block-title">Test it live in the editor</p><p>Enter test values in the editor and watch the display switch between <em>Currently visible</em> and <em>Currently hidden</em>. That way you can verify the condition without publishing the page.</p></div><h2 id="advanced-apptivescript" tabindex="-1">Advanced: ApptiveScript <a class="header-anchor" href="#advanced-apptivescript" aria-label="Permalink to &quot;Advanced: ApptiveScript&quot;">​</a></h2><p>For cases the simple selection doesn&#39;t cover, there&#39;s <strong>Advanced (ApptiveScript)</strong>. The placeholder shows the syntax:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>formValues.get(&#39;age&#39;).greaterThan(18)</span></span></code></pre></div><p>Access happens via the field&#39;s <strong>Key</strong> — not its label.</p><div class="warning custom-block"><p class="custom-block-title">Set keys in advance</p><p>If you change an input block&#39;s key, existing conditions stop matching — without any error message. Choose descriptive keys <strong>before</strong> you start using them.</p><p>Use <strong>Manage keys</strong> to see all keys on a page. → <a href="/en/seiten/eingabebloecke">Input blocks</a></p></div><p>For most everyday cases, the simple field/condition/value selection is enough. Beyond that: <a href="/en/apptivescript/schreibweise">Syntax</a>, <a href="/en/apptivescript/werte-referenzieren">Referencing values</a>, and the <a href="/en/referenz/apptivescript-funktionen">function reference</a>. The condition must ultimately evaluate to a boolean value.</p><div class="warning custom-block"><p class="custom-block-title">Two failure patterns, two causes</p><p>A block that <strong>never</strong> appears usually points to a wrong key — the condition is then always false. A block that <strong>always</strong> appears usually points to a typo in the expression: on a broken expression, the block stays visible.</p></div><h2 id="typical-uses" tabindex="-1">Typical uses <a class="header-anchor" href="#typical-uses" aria-label="Permalink to &quot;Typical uses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Condition</th></tr></thead><tbody><tr><td>Follow-up question only on rejection</td><td><code>Decision</code> <em>is false</em></td></tr><tr><td>Extra fields only for &quot;Other&quot;</td><td><code>Category</code> <em>equals</em> <code>Other</code></td></tr><tr><td>Adults-only section</td><td><code>Age</code> <em>is greater than</em> <code>17</code></td></tr><tr><td>Follow-up on a poor rating</td><td><code>Rating</code> <em>is less than</em> <code>3</code></td></tr><tr><td>Details only when provided</td><td><code>Order number</code> <em>is not empty</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Shorter forms through conditional fields</p><p>Instead of presenting everything to everyone, show few fields up front and reveal more only when needed. This noticeably lowers the abandonment rate — especially on mobile.</p><p>This is also the main reason to build a <a href="/en/seiten/was-sind-seiten">Page</a> instead of a <a href="/en/formulare/formular-erstellen">form</a>: forms have no conditional display.</p></div><h2 id="showing-and-hiding-entire-sections" tabindex="-1">Showing and hiding entire sections <a class="header-anchor" href="#showing-and-hiding-entire-sections" aria-label="Permalink to &quot;Showing and hiding entire sections&quot;">​</a></h2><p>Visibility applies to <strong>one block</strong>. Set it on a <a href="/en/seiten/layout-bloecke">layout</a>, and its entire contents disappear along with it.</p><div class="tip custom-block"><p class="custom-block-title">Use a layout as a container</p><p>If five fields should appear together, put them inside a vertical layout and set the condition <strong>once</strong> on that — instead of five times individually. That&#39;s clearer and easier to change.</p></div><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">What visibility doesn&#39;t do</p><ul><li><strong>Not access control.</strong> A hidden block isn&#39;t protected, just invisible. For real restrictions, use <a href="/en/zusammenarbeit/zugriff-beschraenken">access restrictions</a>.</li><li><strong>Not inside HTML blocks.</strong> The condition applies to the <a href="/en/seiten/html-bloecke">HTML block</a> as a whole, not to parts within it.</li><li><strong>Only one condition per block</strong> via the simple selection. Combinations need <code>logicalAnd</code> or <code>logicalOr</code> → <a href="/en/apptivescript/schreibweise">Syntax</a>.</li></ul></div><div class="warning custom-block"><p class="custom-block-title">Required fields inside hidden blocks</p><p>Check how a hidden required field behaves before putting the page into production. Test both cases — condition met and not met — all the way through submission.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/seiten/eingabebloecke">Input blocks</a></li><li><a href="/en/seiten/layout-bloecke">Layout blocks</a></li><li><a href="/en/seiten/seite-erstellen">Creating and editing a page</a></li></ul>',30)])])}const b=t(a,[["render",s]]);export{u as __pageData,b as default};
